Dokumen: Menyimpan dan mencari vektor di Milvus. Sumber: memakai-milvus.md. Bagian: Menyiapkan helper dan file config.
Bagian ini menjelaskan konfigurasi awal collection my_collection di Milvus, termasuk skema field seperti id dan embedding, serta indeks HNSW untuk pencarian vektor yang efisien.

```json title="milvus_config.json"
    {
        "connection": {
            "uri": "http://localhost",
            "port": 19530,
            "db_name": "default"
        },
        "collections": [
            {
                "collection_name": "my_collection",
                "shards_num": 2,
                "description": "My first collection",
                "milvus_schema": {
                    "auto_id": true,
                    "enable_dynamic_field": true,
                    "fields": [
                        {
                            "field_name": "id",
                            "datatype": "VARCHAR",
                            "max_length": 128,
                            "is_primary": true
                        },
                        {
                            "field_name": "embedding",
                            "datatype": "FLOAT_VECTOR",
                            "dim": 768
                        }
                    ],
                    "functions": []
                },
                "indexes": [
                    {
                        "field_name": "embedding",
                        "index_name": "emb_idx",
                        "index_type": "HNSW",
                        "metric_type": "COSINE",
                        "params": {
                            "M": 16,
                            "efConstruction": 200
                        }
                    }
                ]
            }
        ]
    }
